package com.hbm.machine.radar;
import com.google.gson.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import net.neoforged.fml.loading.FMLPaths;
/** Original hbm machine config keys, grouped under radar/radar_large; no gameplay values are guessed. */
public final class RadarConfig{public static int maxPower=100000,consumption=500,range=1000,buffer=30,altitude=55,chunkLoadCap=10,largeRange=3000;public static boolean generateChunks;public static void load(){try{Path file=FMLPaths.CONFIGDIR.get().resolve("hbm-radar.json");var gson=new GsonBuilder().setPrettyPrinting().create();if(!Files.exists(file)){var all=new JsonObject();var r=new JsonObject();r.addProperty("L:powerCap",maxPower);r.addProperty("L:consumption",consumption);r.addProperty("I:radarRange",range);r.addProperty("I:radarBuffer",buffer);r.addProperty("I:radarAltitude",altitude);r.addProperty("I:chunkLoadCap",chunkLoadCap);r.addProperty("B:generateChunks",generateChunks);all.add("radar",r);var l=new JsonObject();l.addProperty("I:radarLargeRange",largeRange);all.add("radar_large",l);Files.createDirectories(file.getParent());Files.writeString(file,gson.toJson(all)+"\n",StandardCharsets.UTF_8);}var all=JsonParser.parseString(Files.readString(file)).getAsJsonObject();if(all.has("radar")){var r=all.getAsJsonObject("radar");maxPower=integer(r,"L:powerCap",maxPower);consumption=integer(r,"L:consumption",consumption);range=integer(r,"I:radarRange",range);buffer=integer(r,"I:radarBuffer",buffer);altitude=integer(r,"I:radarAltitude",altitude);chunkLoadCap=integer(r,"I:chunkLoadCap",chunkLoadCap);if(r.has("B:generateChunks"))generateChunks=r.get("B:generateChunks").getAsBoolean();}if(all.has("radar_large"))largeRange=integer(all.getAsJsonObject("radar_large"),"I:radarLargeRange",largeRange);}catch(java.io.IOException e){throw new IllegalStateException("Cannot read original radar configuration",e);}}private static int integer(JsonObject o,String key,int fallback){return o.has(key)?o.get(key).getAsInt():fallback;}private RadarConfig(){}}
